define(["mod_bookflow/progress_tracker"],function(ProgressTracker){const init=function(bookflowId){document.addEventListener("click",function(event){const link=event.target.closest("[data-bookflow-download]");if(!link){return}ProgressTracker.complete(bookflowId,Number(link.dataset.bookflowDownload),100,{clicked:true})})};return{init:init}});